INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-cucumber-introduction', '黄瓜传入中原', 'commerce', 'circa', 'year', '按张骞两次出使西域及西汉西域交流兴起的背景，采用约前138—前119年作为传播窗口；具体首传事件无可确定的单一年份，前119年仅作时间轴窗口内锚点。', -119, 12, -1405, -138, 1, -1644, -119, 12, -1405, '黄瓜（胡瓜）经西域农作物交流路线传入中原，传统叙述常将传播与张骞通西域联系起来。西汉交流推动葡萄、苜蓿等多种域外作物进入中国；黄瓜具体首次引种年月无法精确确定，北魏《齐民要术》已载其栽培方法。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-maize-introduction', '玉米传入中国', 'commerce', 'circa', 'year', '通常认为在16世纪中叶前后传入；1560年《平凉府志》是早期可核证据之一，实际引种可能更早。因路线和最初落地时间有争议，采用约1500—1560年窗口。', 1530, 12, 18371, 1500, 1, 18000, 1560, 12, 18731, '玉米原产美洲，随大航海时代后的跨洋贸易传播到中国。学界提出西北陆路、西南陆路和东南海路等路线，至明代中叶已传入多个地区；耐旱、耐瘠特性使它后来成为山地重要粮食作物。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-sweet-potato-introduction', '甘薯经海路传入福建', 'commerce', 'circa', 'year', '不同记载分别系于万历十年前后、万历十一至十二年及万历二十一年（1593）；以1582—1593年作约略窗口，1593年仅作常见叙事锚点。', 1593, 12, 19127, 1582, 1, 18984, 1593, 12, 19127, '甘薯由美洲经西班牙航路进入菲律宾等地，随后通过海上贸易传入福建。地方志与农史著作保留了陈益、陈振龙等不同引种路线，甘薯耐瘠高产，后来成为重要的救荒作物。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-chili-introduction', '辣椒传入中国', 'commerce', 'circa', 'year', '具体首传路线和年份未定；研究将其传入中国置于16世纪后期至17世纪前期，取约1570—1650年窗口。', 1600, 12, 19211, 1570, 1, 18840, 1650, 12, 19811, '美洲辣椒经欧洲殖民贸易网络传入亚洲，再由海陆交通进入中国。传入初期多作观赏或药用植物，之后才逐步进入各地饮食并成为区域特色作物。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-tomato-introduction', '番茄传入中国', 'commerce', 'circa', 'year', '中国首次引种时间难以确考，研究多置于17—18世纪；1617年《植品》出现相关名称只能提供传入已发生的年代线索，不能视为引种当年。取约1600—1800年窗口。', 1700, 12, 20411, 1600, 1, 19200, 1800, 12, 21611, '番茄原产美洲，随西班牙海上贸易经菲律宾及东南亚传入中国南方沿海。初期作为观赏植物和稀见蔬果，后来才逐渐进入日常饮食。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-tobacco-introduction', '烟草传入中国', 'commerce', 'circa', 'year', '研究多将引入时间置于16—17世纪；《景岳全书》在1624年回述万历年间闽、广已有烟草，嘉靖年间烟具也提示传播可能较早。取约1540—1624年窗口，不以现存证据年份代表首传年。', 1590, 12, 19091, 1540, 1, 18480, 1624, 12, 19499, '烟草原产美洲，约在明代中后期经菲律宾吕宋及东南沿海贸易路线传入中国，随后由闽、粤等地向内地扩散，逐渐成为重要经济作物和消费品。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-song-guangzhou-shipping-office', '广州设市舶司', 'commerce', 'point', 'year', '开宝四年（971）；广州博物馆所藏北宋《大宋新修广利王庙之碑》记载平南汉后设司。', 971, 12, 11663, NULL, NULL, NULL, NULL, NULL, NULL, '北宋平定南汉后在广州设置市舶司，专门管理海外商船、蕃货和贸易事务。此后宋廷陆续在东南沿海增设机构，海贸成为国家财政与跨区域交流的重要组成。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-song-tea-horse-trade', '茶马互市兴起', 'commerce', 'point', 'year', '熙宁七年（1074）被视为宋代茶马制度形成的重要年份；贸易实践和机构调整持续多年。', 1074, 12, 12899, NULL, NULL, NULL, NULL, NULL, NULL, '宋廷在四川等地设置茶马贸易机构，以茶换取西北及西南地区所需战马，并以官府专營、茶引等方式管理交易。茶马互市把边疆贸易、軍需供给与区域治理联系起来。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-longqing-yuegang-opening', '隆庆开海', 'commerce', 'point', 'year', '隆庆元年（1567）；采用海澄县志等记载的开港年份。', 1567, 12, 18815, NULL, NULL, NULL, NULL, NULL, NULL, '明廷在福建月港有限度开放民间海上贸易，商船可依规出洋，月港成为东南沿海重要贸易港。政策并未废除海禁，走私、朝贡贸易与许可贸易仍交织并存。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-qing-maritime-trade-reopened', '清廷开海', 'commerce', 'point', 'year', '康熙二十三年（1684）解除海禁、设置海关；开放港口的诏令及实施在1685年，事件以政策转折年定位。', 1684, 12, 20219, NULL, NULL, NULL, NULL, NULL, NULL, '平定台湾后，清廷解除海禁并设粤、闽、浙、江四海关管理海上贸易与征税；次年开放广州、漳州、宁波、云台山等贸易港。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;
INSERT INTO events (id, name, kind, time_mode, precision, date_note, at_year, at_month, at_abs, start_year, start_month, start_abs, end_year, end_month, end_abs, summary, meaning, content, location_id) VALUES ('commerce-qing-canton-system', '广州一口通商', 'commerce', 'point', 'year', '乾隆二十二年（1757）政策转折；各口岸执行和限制逐渐落实，不将其解释为所有对外贸易一概中止。', 1757, 12, 21095, NULL, NULL, NULL, NULL, NULL, NULL, '清廷将西洋商船贸易集中于广州，外商主要通过广州行商体系交易。广州由此成为清代中西贸易的核心口岸，这一格局延续至鸦片战争前后。', NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kind = EXCLUDED.kind, time_mode = EXCLUDED.time_mode, precision = EXCLUDED.precision, date_note = EXCLUDED.date_note, at_year = EXCLUDED.at_year, at_month = EXCLUDED.at_month, at_abs = EXCLUDED.at_abs, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_abs = EXCLUDED.start_abs, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_abs = EXCLUDED.end_abs, summary = EXCLUDED.summary, meaning = EXCLUDED.meaning, content = EXCLUDED.content, location_id = EXCLUDED.location_id;

